package thaumcraft.api.casters;
import net.minecraft.nbt.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import thaumcraft.common.items.casters.CasterRegistries;
import thaumcraft.common.items.casters.foci.*;
class FocusPackageTest{
    @Test void twentySourceNodesPlusRootAreRegisteredAndSettingsRoundTrip(){CasterRegistries.registerNodes();assertEquals(21,FocusEngine.elements.size());assertTrue(FocusEngine.getElement("ROOT") instanceof FocusMediumRoot);var projectile=new FocusMediumProjectile();projectile.getSetting("speed").setValue(5);projectile.getSetting("option").setValue(2);var fire=new FocusEffectFire();fire.getSetting("power").setValue(4);var package1=new FocusPackage();package1.addNode(projectile);package1.addNode(fire);package1.setComplexity(15);var package2=new FocusPackage();package2.deserialize(package1.serialize());assertEquals(15,package2.getComplexity());assertEquals(5,((FocusNode)package2.nodes.get(0)).getSettingValue("speed"));assertEquals(2,((FocusNode)package2.nodes.get(0)).getSettingValue("option"));assertEquals(4,package2.getFocusEffects()[0].getSettingValue("power"));}
    @Test void splitBranchesRemainRealPackagesWithRecursiveEffects(){CasterRegistries.registerNodes();var split=new FocusModSplitTarget();var branch=new FocusPackage();branch.addNode(new FocusEffectHeal());split.getSplitPackages().add(branch);var package1=new FocusPackage();package1.addNode(split);var package2=new FocusPackage();package2.deserialize(package1.serialize());assertEquals("thaumcraft.HEAL",package2.getFocusEffects()[0].getKey());assertEquals(.75F,((FocusModSplit)package2.nodes.get(0)).getPowerMultiplier());}
    @Test void terminalPackageSuppressesFollowingNodesAsSource(){CasterRegistries.registerNodes();var outer=new FocusPackage();var child=new FocusPackage();child.addNode(new FocusEffectAir());outer.addNode(child);outer.addNode(new FocusEffectFlux());var copy=new FocusPackage();copy.deserialize(outer.serialize());assertEquals(1,copy.nodes.size());assertEquals("thaumcraft.AIR",copy.getFocusEffects()[0].getKey());}
    @Test void iterativeGuardRejectsOversizedListsStringsAndSplitNesting(){var tag=new CompoundTag();var list=new ListTag();for(int i=0;i<257;i++)list.add(new CompoundTag());tag.put("nodes",list);assertFalse(FocusSerializationRules.isBounded(tag));tag=new CompoundTag();tag.putString("oversized","x".repeat(8193));assertFalse(FocusSerializationRules.isBounded(tag));var root=new CompoundTag();var current=root;for(int i=0;i<130;i++){var child=new CompoundTag();current.put("packages",child);current=child;}assertFalse(FocusSerializationRules.isBounded(root));var package1=new FocusPackage();assertDoesNotThrow(()->package1.deserialize(root));assertTrue(package1.nodes.isEmpty());}
    @Test void sourceNodeFormulasAndPowerAttenuation(){var projectile=new FocusMediumProjectile();assertEquals(4,projectile.getComplexity());projectile.getSetting("speed").setValue(5);projectile.getSetting("option").setValue(1);assertEquals(9,projectile.getComplexity());var cloud=new FocusMediumCloud();assertEquals(7,cloud.getComplexity());assertEquals(.5F,cloud.getPowerMultiplier());assertEquals(.33F,new FocusMediumSpellBat().getPowerMultiplier());var exchange=new FocusEffectExchange();assertEquals(3,exchange.getComplexity());exchange.getSetting("fortune").setValue(2);assertEquals(9,exchange.getComplexity());}
}
